/* apm3.c - Senjin Aleste: native replacement for apm_x86.dll (Sega ALL.Net P-ras Multi Ver.3).
 * PC-code reimplementation (no emulation) of the 106 APM3 services: free play, no ALL.Net
 * network by default, system inputs read from the XInput gamepad, local paths.
 * On load: applies the aleste.ini [config] settings to config.txt (read by the game).
 * Version: see version.h (generated by _kit/version/gen_version.py). */
#include <windows.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <string.h>
#include "version.h"

#define API __stdcall
typedef DWORD D;

/* ---------- settings (aleste.ini, [apm] section) ---------- */
static wchar_t g_root[MAX_PATH];          /* exe folder, with trailing '\' */
static char g_ini[MAX_PATH], g_cfg[MAX_PATH], g_log[MAX_PATH];
static int g_online = 0, g_log_on = 0;
static wchar_t g_gameid[16] = L"SBRF", g_keychip[64] = L"A00E01A0000000000", g_location[64] = L"PC";

static void logf_(const char *fmt, ...) {
    if (!g_log_on) return;
    FILE *f = fopen(g_log, "a"); if (!f) return;
    va_list a; va_start(a, fmt); vfprintf(f, fmt, a); va_end(a); fputc('\n', f); fclose(f);
}

/* Replaces the KEY=... lines of config.txt with the values from aleste.ini [config].
 * Works byte by byte: Shift-JIS comments and line endings are preserved. */
/* Buttons: the launcher picks which gamepad button (XInput no. 1-14) does Shot / Power-up / Semi-auto / Blow /
 * Pause / Reset (g_padmap); config.txt gets fixed values = cabinet buttons 1 to 6 (inputs 6..11), like the
 * native Linux version. Cabinet menus confirm with cabinet button 1, i.e. with the button assigned to Shot. */
static int g_padmap[6] = { 11, 12, 13, 14, 6, 0 };
static const char *g_padkeys[6] = { "BUTTON_01", "BUTTON_02", "BUTTON_03", "BUTTON_04", "BUTTON_PAUSE", "BUTTON_RESET" };
/* Settings shared between the launcher and the game (3-way merge, same as the native build's sa_config.c):
 * aleste.ini [config] = launcher values; config.txt = the game's own file (it rewrites it: menu cursors STORY_*,
 * TRAINING_*...); aleste.ini [config.sync] = values applied at the previous start. A key changed in the launcher since
 * then is written to config.txt; otherwise a value changed by the game is copied back to aleste.ini (the launcher
 * then shows it). Keys only in config.txt are added to aleste.ini. BUTTON_xx are handled apart. */
static void merge_config(void) {
    static char txt[65536]; FILE *f = fopen(g_cfg, "rb"); if (!f) return;
    size_t n = fread(txt, 1, sizeof txt - 1, f); fclose(f); txt[n] = 0;
    int imported = 0;
    for (char *p = txt; *p; ) {
        char *e = strchr(p, '\n'); if (!e) e = p + strlen(p);
        char *eq = (*p != ';' && *p != '\r' && p < e) ? memchr(p, '=', (size_t)(e - p)) : NULL;
        if (eq && eq - p < 63 && strncmp(p, "BUTTON_", 7)) {
            char k[64], c[96], a[96], sn[96]; memcpy(k, p, (size_t)(eq - p)); k[eq - p] = 0;
            char *ve = eq + 1; while (ve < e && *ve != '\r' && *ve != ';') ve++;
            size_t vl = (size_t)(ve - eq - 1); if (vl > 95) vl = 95; memcpy(c, eq + 1, vl); c[vl] = 0;
            while (vl && (c[vl - 1] == ' ' || c[vl - 1] == '\t')) c[--vl] = 0;
            GetPrivateProfileStringA("config", k, "\x01", a, sizeof a, g_ini);
            GetPrivateProfileStringA("config.sync", k, "\x01", sn, sizeof sn, g_ini);
            int has_a = a[0] != 1, has_s = sn[0] != 1;
            if (!has_a || (has_s && !strcmp(a, sn) && strcmp(a, c))) { WritePrivateProfileStringA("config", k, c, g_ini); strcpy(a, c); imported++; }
            if (!has_s || strcmp(sn, a)) WritePrivateProfileStringA("config.sync", k, a, g_ini);
        }
        p = *e ? e + 1 : e;
    }
    if (imported) logf_("config: %d setting(s) taken from config.txt (changed in the game)", imported);
}
static void sync_config(void) {
    merge_config();
    /* keys: the pairs copied from raw (at most sizeof raw) + the fixed pairs (~135 bytes) + terminator */
    static char raw[16384], keys[sizeof raw + 256];
    DWORD rn = GetPrivateProfileSectionA("config", raw, sizeof raw, g_ini);
    /* copy the pairs except BUTTON_xx (kept in g_padmap), then the fixed values */
    DWORD n = 0;
    for (char *k = raw; rn && *k; k += strlen(k) + 1) {
        int pk = 0; for (int i = 0; i < 6; i++) { size_t l = strlen(g_padkeys[i]); if (!strncmp(k, g_padkeys[i], l) && k[l] == '=') { g_padmap[i] = atoi(k + l + 1); pk = 1; } }
        if (!strncmp(k, "BUTTON_UP=", 10) || !strncmp(k, "BUTTON_DOWN=", 12) || !strncmp(k, "BUTTON_LEFT=", 12) || !strncmp(k, "BUTTON_RIGHT=", 13)) pk = 1;
        if (!pk) { size_t l = strlen(k) + 1; if (n + l >= sizeof keys) break; memcpy(keys + n, k, l); n += (DWORD)l; }
    }
    static const char *fixed[] = { "BUTTON_UP=1", "BUTTON_DOWN=2", "BUTTON_LEFT=3", "BUTTON_RIGHT=4", "BUTTON_01=6", "BUTTON_02=7",
        "BUTTON_03=8", "BUTTON_04=9", "BUTTON_PAUSE=10", "BUTTON_RESET=11" };
    for (int i = 0; i < 10; i++) { size_t l = strlen(fixed[i]) + 1; if (n + l >= sizeof keys) break; memcpy(keys + n, fixed[i], l); n += (DWORD)l; }
    keys[n] = 0;
    logf_("gamepad: Shot=%d Power-up=%d Semi-auto=%d Blow=%d Pause=%d Reset=%d", g_padmap[0], g_padmap[1], g_padmap[2], g_padmap[3], g_padmap[4], g_padmap[5]);
    FILE *f = fopen(g_cfg, "rb"); if (!f) return;
    long sz = -1; if (!fseek(f, 0, SEEK_END)) sz = ftell(f);
    if (sz < 0 || fseek(f, 0, SEEK_SET)) { fclose(f); logf_("config.txt: cannot get its size"); return; }
    char *src = malloc((size_t)sz + 1);
    if (!src || fread(src, 1, (size_t)sz, f) != (size_t)sz) { fclose(f); free(src); logf_("config.txt: read failed"); return; }
    fclose(f); src[sz] = 0;
    /* a line's output is at most its input + one new value (< n) + '\n': before each line, room is ensured
     * for that plus the rest of the input (config.txt may repeat a key on several lines) */
    size_t cap = (size_t)sz + n + 64, o = 0; char *dst = malloc(cap); int changed = 0;
    if (!dst) { free(src); return; }
    char *p = src;
    while (*p) {
        size_t need = o + (size_t)(src + sz - p) + n + 2;
        if (need > cap) {
            char *nd = realloc(dst, need * 2); if (!nd) { free(src); free(dst); return; }
            dst = nd; cap = need * 2;
        }
        char *e = p; while (*e && *e != '\n') e++;
        int handled = 0;
        if (*p != ';') {
            char *eq = memchr(p, '=', e - p);
            if (eq) {
                for (char *k = keys; *k; k += strlen(k) + 1) {
                    char *ke = strchr(k, '='); if (!ke) continue;
                    size_t kl = ke - k;
                    if ((size_t)(eq - p) == kl && !memcmp(p, k, kl)) {
                        char *vend = eq + 1; while (vend < e && *vend != '\r' && *vend != ';') vend++;
                        size_t ol = vend - (eq + 1), nl = strlen(ke + 1);
                        if (ol != nl || memcmp(eq + 1, ke + 1, nl)) changed = 1;
                        memcpy(dst + o, p, kl + 1); o += kl + 1;
                        memcpy(dst + o, ke + 1, nl); o += nl;
                        memcpy(dst + o, vend, e - vend); o += e - vend;
                        handled = 1; break;
                    }
                }
            }
        }
        if (!handled) { memcpy(dst + o, p, e - p); o += e - p; }
        if (*e == '\n') dst[o++] = '\n', e++;
        p = e;
    }
    if (changed && (f = fopen(g_cfg, "wb"))) { fwrite(dst, 1, o, f); fclose(f); logf_("config.txt updated from aleste.ini"); }
    free(src); free(dst);
}

static int g_aime;
static void load_settings(void) {
    char tmp[128];
    g_aime = GetPrivateProfileIntA("apm", "aime", 0, g_ini);
    g_online = GetPrivateProfileIntA("apm", "online", 0, g_ini);
    g_log_on = GetPrivateProfileIntA("apm", "log", 0, g_ini);
    if (GetPrivateProfileStringA("apm", "game_id", "", tmp, sizeof tmp, g_ini)) MultiByteToWideChar(CP_ACP, 0, tmp, -1, g_gameid, 16);
    if (GetPrivateProfileStringA("apm", "keychip", "", tmp, sizeof tmp, g_ini)) MultiByteToWideChar(CP_ACP, 0, tmp, -1, g_keychip, 64);
    if (GetPrivateProfileStringA("apm", "location", "", tmp, sizeof tmp, g_ini)) MultiByteToWideChar(CP_ACP, 0, tmp, -1, g_location, 64);
}

